select case when s.rating >= 3.9 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end as rating_bucket, count(i.quantity) as quantity_count, min(i.last_restock) as first_last_restock from inventory i left join products p on i.product_id = p.id inner join suppliers s on p.supplier_id = s.id group by case when s.rating >= 3.9 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end
